
USE sistema_estudiantes;








SELECT 'Usuarios' AS tabla, COUNT(*) AS total FROM usuarios
UNION ALL SELECT 'Apoderados', COUNT(*) FROM apoderados
UNION ALL SELECT 'Estudiantes', COUNT(*) FROM estudiantes;

SELECT nivel, grado, seccion, COUNT(*) AS alumnos
FROM estudiantes GROUP BY nivel, grado, seccion ORDER BY nivel, grado, seccion;